\set ON_ERROR_STOP on
\if :{?author_id}
\else
  \echo 'Missing author_id'
  \quit
\endif

BEGIN;
DO $$ BEGIN
  IF current_database() <> 'toeic_dev_fresh' THEN
    RAISE EXCEPTION 'This fixture is restricted to toeic_dev_fresh';
  END IF;
END $$;

CREATE TEMP TABLE demo_lessons(n integer, category text, title text, summary text, body text, difficulty text) ON COMMIT DROP;
INSERT INTO demo_lessons VALUES
 (2,'GRAMMAR','Present simple and workplace routines','Practice everyday routines and subject agreement.',
  'Use the present simple for routines. A singular subject takes an -s ending: The manager reviews the report every Monday. Use do or does in questions: Does the manager review the report? Do not use the present continuous for a regular schedule.','EASY'),
 (3,'VOCAB','Workplace email vocabulary','Learn common TOEIC email terms.',
  'An invoice lists the amount a customer must pay. A deadline is the last time to finish a task. A schedule lists planned activities. A participant attends an event. Please send the invoice before the deadline and check the workshop schedule.','EASY'),
 (4,'READING','Reading a workshop notice','Find dates, locations and instructions in a short notice.',
  'Workshop notice: The customer workshop begins at 9 a.m. on Friday in Room 3. Participants should register by Thursday and bring a notebook. Coffee is available at reception. Read the heading first, then scan for the requested detail.','EASY'),
 (5,'LISTENING','Listening for times and places','Identify key details in an announcement transcript.',
  'Sample announcement transcript: Good morning. The customer workshop will begin at nine o clock in Room Three. Please collect your handouts from reception before entering. Listen for the time, room number and action requested. This sample has a transcript but no audio file.','EASY'),
 (6,'STRATEGIES','TOEIC Reading time management','Plan a steady pace across Reading tasks.',
  'Read the question before scanning the passage for names, dates and numbers. Answer direct detail questions first. If one question takes too long, mark it and move on. Return with the remaining time; check the exact wording against the passage.','MEDIUM'),
 (7,'DOCS','TOEIC practice guide','Use the local practice materials effectively.',
  'Use the Practice page to answer published questions. Review the explanation after submission. Practice questions require published question versions. Listening audio and official score conversion are not provided by this sample lesson.','EASY'),
 (8,'VOCAB','Meetings and schedules vocabulary','Understand common words used in meetings and calendars.',
  'Agenda /əˈdʒendə/ (noun): a list of topics to discuss; collocation: set the agenda. Appointment /əˈpɔɪntmənt/ (noun): an arranged meeting; schedule an appointment. Postpone /poʊstˈpoʊn/ (verb): move an event to a later time; postpone a meeting. Reschedule /ˌriːˈskedʒuːl/ (verb): arrange a new time; reschedule an interview. Venue /ˈvenjuː/ (noun): the place where an event happens; conference venue. Attend /əˈtend/ (verb): be present at an event; attend a seminar. The venue changed, so we rescheduled the appointment and updated the agenda.','EASY'),
 (9,'VOCAB','Office communication vocabulary','Use practical words for messages and documents.',
  'Attachment /əˈtætʃmənt/ (noun): a file sent with an email; email attachment. Confirm /kənˈfɜːrm/ (verb): state that something is certain; confirm receipt. Forward /ˈfɔːrwərd/ (verb): send a message to another person; forward an email. Inquiry /ɪnˈkwaɪəri/ (noun): a request for information; customer inquiry. Notify /ˈnoʊtɪfaɪ/ (verb): formally tell someone; notify employees. Recipient /rɪˈsɪpiənt/ (noun): a person who receives something; intended recipient. Please confirm receipt of the attachment and forward the inquiry to the correct recipient.','EASY'),
 (10,'VOCAB','Hiring and personnel vocabulary','Learn frequent recruitment and employment terms.',
  'Applicant /ˈæplɪkənt/ (noun): a person applying for a job; qualified applicant. Candidate /ˈkændɪdeɪt/ (noun): a person considered for a position; interview a candidate. Vacancy /ˈveɪkənsi/ (noun): an available job; fill a vacancy. Qualification /ˌkwɑːlɪfɪˈkeɪʃn/ (noun): a skill or credential needed for work; minimum qualification. Recruit /rɪˈkruːt/ (verb): find and hire employees; recruit staff. Supervisor /ˈsuːpərvaɪzər/ (noun): a person who manages employees; report to a supervisor. The supervisor will interview every qualified applicant for the vacancy.','MEDIUM'),
 (11,'VOCAB','Sales and customer service vocabulary','Handle orders, payments and customer requests.',
  'Refund /ˈriːfʌnd/ (noun): money returned to a customer; request a refund. Receipt /rɪˈsiːt/ (noun): proof of payment; keep the receipt. Discount /ˈdɪskaʊnt/ (noun): a reduction in price; offer a discount. Purchase /ˈpɜːrtʃəs/ (noun or verb): something bought or the act of buying; make a purchase. Complaint /kəmˈpleɪnt/ (noun): a statement of dissatisfaction; handle a complaint. Satisfied /ˈsætɪsfaɪd/ (adjective): pleased because expectations were met; satisfied customer. Keep your receipt because it is required when you request a refund for a purchase.','EASY'),
 (12,'VOCAB','Shipping and logistics vocabulary','Follow deliveries and warehouse operations.',
  'Shipment /ˈʃɪpmənt/ (noun): goods sent together; track a shipment. Delivery /dɪˈlɪvəri/ (noun): the act of bringing goods; delivery date. Warehouse /ˈwerhaʊs/ (noun): a building used to store goods; warehouse staff. Inventory /ˈɪnvəntɔːri/ (noun): goods that a company has; check inventory. Supplier /səˈplaɪər/ (noun): a company that provides goods; local supplier. Delay /dɪˈleɪ/ (noun or verb): a late arrival or to make something late; shipping delay. The supplier reported a delay, so the shipment will reach the warehouse after the expected delivery date.','MEDIUM'),
 (13,'VOCAB','Business travel vocabulary','Prepare for flights, hotels and work trips.',
  'Itinerary /aɪˈtɪnəreri/ (noun): a detailed travel plan; travel itinerary. Accommodation /əˌkɑːməˈdeɪʃn/ (noun): a place to stay; book accommodation. Departure /dɪˈpɑːrtʃər/ (noun): the act or time of leaving; departure time. Destination /ˌdestɪˈneɪʃn/ (noun): the place someone is traveling to; final destination. Reservation /ˌrezərˈveɪʃn/ (noun): an arrangement to keep a seat or room; hotel reservation. Reimburse /ˌriːɪmˈbɜːrs/ (verb): repay money spent for work; reimburse travel expenses. Check the itinerary and hotel reservation before departure, and keep receipts so the company can reimburse you.','MEDIUM'),
 (14,'VOCAB','Finance and budgeting vocabulary','Understand common company finance terms.',
  'Budget /ˈbʌdʒɪt/ (noun): a plan for spending money; annual budget. Expense /ɪkˈspens/ (noun): money spent for a purpose; business expense. Revenue /ˈrevənuː/ (noun): income earned by a business; increase revenue. Profit /ˈprɑːfɪt/ (noun): money remaining after costs; make a profit. Estimate /ˈestɪmət/ (noun): an approximate calculation; cost estimate. Affordable /əˈfɔːrdəbl/ (adjective): not too expensive; affordable price. The cost estimate is within the annual budget, and higher revenue should increase the company profit.','MEDIUM'),
 (15,'VOCAB','Facilities and maintenance vocabulary','Discuss buildings, equipment and repairs.',
  'Equipment /ɪˈkwɪpmənt/ (noun): tools or machines used for work; office equipment. Facility /fəˈsɪləti/ (noun): a building or service for a purpose; training facility. Inspect /ɪnˈspekt/ (verb): examine something carefully; inspect equipment. Maintenance /ˈmeɪntənəns/ (noun): work that keeps something in good condition; routine maintenance. Renovate /ˈrenəveɪt/ (verb): repair and improve a building; renovate an office. Replace /rɪˈpleɪs/ (verb): put something new in place of something old; replace a printer. Staff will inspect the equipment before routine maintenance begins at the renovated facility.','MEDIUM'),
 (16,'GRAMMAR','Present perfect in progress reports','Connect completed work and present results.',
  'Form: have or has plus a past participle. The team has completed the quarterly report, so the manager can review it now. Use the simple past when a finished time is stated: The team completed the report yesterday. Already commonly appears in affirmative sentences: We have already sent the files. Yet commonly appears in questions and negatives: Have you received the invoice yet? We have not received it yet. Compare: She has worked here since 2022 describes a period continuing to now; she worked here in 2022 does not say she still works here. In a TOEIC email, check time expressions before choosing the verb form.','MEDIUM'),
 (17,'GRAMMAR','Conditionals for workplace decisions','Read conditions, results and polite proposals.',
  'Use if plus present simple and will plus base verb for a possible future result: If the shipment arrives today, we will dispatch the orders tomorrow. Do not put will after if in this pattern. Use if plus past simple and would plus base verb for a hypothetical situation: If we had a larger room, we would invite more participants. Unless means if not: Unless the supplier confirms the date, we cannot announce the schedule. A condition can appear before or after the result: We will reschedule the meeting if the presenter is unavailable. Identify which event must happen first when answering a TOEIC question.','MEDIUM'),
 (18,'GRAMMAR','Passive voice in notices and emails','Understand who receives an action.',
  'Form the passive with be plus a past participle. Present: All applications are reviewed by the hiring team. Past: The invoices were sent on Monday. Future: The new equipment will be installed next week. Use the passive when the action or result matters more than the person doing it. Compare active: The technician repaired the printer. Passive: The printer was repaired by the technician. In a notice, subject and tense carry the answer: The conference room is reserved for Friday does not mean it was reserved for every day. A by phrase names the agent only when needed.','EASY'),
 (19,'GRAMMAR','Relative clauses in business descriptions','Connect people, things and places to details.',
  'Who describes a person: The applicant who called yesterday has an interview. Which describes a thing: The report which you requested is attached. That can describe a person or thing in a defining clause: The supplier that delivers our paper is local. Where describes a place: The office where the seminar takes place is on the second floor. A defining clause identifies exactly which person or thing is meant; do not separate it with commas. In TOEIC Part 5, check whether the missing word refers to a person, object or place, and whether the following clause already has its own subject and object.','MEDIUM'),
 (20,'READING','Email: a revised workshop schedule','Practice finding changes and required actions.',
  'Subject: Updated customer workshop schedule. Dear participants, the workshop originally planned for Thursday, May 14 will take place on Friday, May 15 in Conference Room B. Registration remains open until Wednesday at 5 p.m. Please bring your confirmation email to the reception desk. The presentation will begin at 9 a.m., followed by a product demonstration at 10:30 a.m. If you can no longer attend, reply by Tuesday so we can offer your seat to another customer. Reading check: What changed? The day and room. What must participants bring? Their confirmation email. Which deadline applies to registration? Wednesday at 5 p.m. Distinguish the reply deadline from the registration deadline.','EASY'),
 (21,'READING','Notice: office renovation and access','Scan a notice for dates, locations and exceptions.',
  'Building notice: Maintenance staff will renovate the third-floor meeting rooms from June 3 through June 7. During this period, employees should use the rooms on the second floor. The reception area and elevators will remain open. Deliveries for the finance department should be left with security on the ground floor before 4 p.m. The renovated rooms are expected to reopen on June 10. Reading check: Which rooms are unavailable? Third-floor meeting rooms. Where should finance deliveries go? Ground-floor security. Does the notice say all elevators are closed? No. Expected to reopen expresses a plan, not a guarantee.','EASY'),
 (22,'READING','Advertisement: business travel package','Compare benefits, restrictions and prices.',
  'Metro Business Hotel offers a weekday package for guests staying at least two nights between September 1 and October 31. The rate includes breakfast, airport shuttle service and access to the meeting lounge. Reservations must be made through the hotel website at least seven days before arrival. Parking and laundry are charged separately. Guests may cancel without a fee up to 48 hours before check-in. Reading check: Is parking included? No. How early must guests book? At least seven days before arrival. When can guests cancel without a fee? Up to 48 hours before check-in. Distinguish included services from separately charged services.','MEDIUM'),
 (23,'LISTENING','Announcement transcript: platform change','Listen for a change and the action requested.',
  'Practice transcript, not an audio recording: Attention passengers traveling to Westport. The 2:40 train will now depart from Platform 6 instead of Platform 4. Boarding begins at 2:25. Passengers with large luggage should use the elevators near the north entrance. We apologize for the change. Listening check: Which platform is correct now? Platform 6. When does boarding begin? 2:25. Where are the elevators? Near the north entrance. The first platform mentioned is no longer correct; listen for now and instead of when an announcement corrects earlier information. No audio asset is attached to this lesson.','EASY'),
 (24,'LISTENING','Conversation transcript: supply order','Track a request, a problem and a next step.',
  'Practice transcript, not an audio recording. A: Have the new printers arrived? B: The supplier delivered two this morning, but the third is delayed until Friday. A: We need three for the training session on Thursday. Could we borrow one from the sales department? B: I will ask their supervisor and let you know by noon. Listening check: What is the problem? One printer has not arrived. When is it expected? Friday. What will the second speaker do? Ask the sales supervisor about borrowing a printer. By noon is the promised update time, not the delivery time. No audio asset is attached to this lesson.','MEDIUM'),
 (25,'STRATEGIES','Part 5: choose from grammar and context','Use a short checklist for sentence completion.',
  'First read the whole sentence and identify the missing function: noun, verb, adjective, adverb or connector. Next check nearby words for agreement, tense and prepositions. Then use the sentence meaning to eliminate choices that are grammatically possible but unsuitable. Example: The manager will ___ the revised schedule to all participants. The word after will must be a base verb; distribute fits the meaning. Do not choose distribution, distributed or distributing after will. Read the completed sentence once more before moving on. This is a study strategy, not a guarantee that one clue alone solves every item.','EASY'),
 (26,'STRATEGIES','Part 7: locate evidence across messages','Read linked documents in order.',
  'In a set of emails or notices, identify the sender, recipient, date and purpose of each document. Read the question before scanning for names, amounts, deadlines and changes. If a second message updates the first, use the latest relevant information. For an inference question, combine only statements actually supported by the documents. Example: an initial email schedules a meeting on Monday; a later reply moves it to Tuesday. The current meeting day is Tuesday. Check whether a question asks about the original plan or the final plan. Avoid answering from outside business knowledge when the passage gives a specific rule.','MEDIUM');

INSERT INTO learning_contents(content_id,category_id,author_id,title,summary,body,difficulty,status,published_at,created_at,updated_at,visibility)
SELECT ('de400000-0000-4000-8000-'||lpad(d.n::text,12,'0'))::uuid,c.category_id,:'author_id'::uuid,
 d.title,d.summary,d.body,d.difficulty,'PUBLISHED',now(),now(),now(),'AUTHENTICATED'
FROM demo_lessons d JOIN content_categories c ON c.code=d.category
ON CONFLICT(content_id) DO NOTHING;

INSERT INTO learning_content_versions(content_version_id,content_id,version_number,title,summary,body,status,published_at,created_by,created_at,updated_at)
SELECT ('de410000-0000-4000-8000-'||lpad(d.n::text,12,'0'))::uuid,
 ('de400000-0000-4000-8000-'||lpad(d.n::text,12,'0'))::uuid,1,d.title,d.summary,d.body,'PUBLISHED',now(),:'author_id'::uuid,now(),now()
FROM demo_lessons d JOIN learning_contents c ON c.content_id=('de400000-0000-4000-8000-'||lpad(d.n::text,12,'0'))::uuid
ON CONFLICT(content_version_id) DO NOTHING;

UPDATE learning_contents c SET current_published_version_id=('de410000-0000-4000-8000-'||right(c.content_id::text,12))::uuid
WHERE c.content_id BETWEEN 'de400000-0000-4000-8000-000000000002' AND 'de400000-0000-4000-8000-000000000026'
 AND c.current_published_version_id IS NULL;
COMMIT;
